<script setup>
import {computed,onBeforeUnmount,ref,shallowRef} from 'vue';
import {Button,Calendar,Cell,CellGroup,Checkbox,Collapse,CollapseItem,Dialog,Field,Picker,Popup,Radio,RadioGroup,Slider,Tab,Tabs,Uploader,showImagePreview} from 'vant';
import StudentUploadHistory from './StudentUploadHistory.vue';
import StudentCourseSettings from './StudentCourseSettings.vue';
const props=defineProps({controller:{type:Object,required:true}}),m=shallowRef(props.controller.snapshot()),a=props.controller.actions;
const unsubscribe=props.controller.subscribe(value=>m.value=value);onBeforeUnmount(()=>{unsubscribe();props.controller.destroy();});
const picker=ref(false),expanded=ref([]),reset=ref(false),confirmed=ref(false),uploadError=ref(''),rewardParent=ref(''),rewardConfirm=ref(false),rewardGame=ref(null),rewardCash=ref(null),rewardEnabled=ref(true);
const columns=computed(()=>m.value.topics.map(t=>({text:t.title,value:t.id}))),currentQuestion=computed(()=>m.value.run?.items[m.value.run.i]);
const tab=computed(()=>m.value.view==='listen'?'learn':m.value.view==='retell'?'recall':'practice');
const services=Object.fromEntries(['deepseek','voice'].map(kind=>[kind,{info:signal=>a.settingsInfo(kind,signal),save:value=>a.saveSettings(kind,value),clear:()=>a.clearSettings(kind),test:signal=>a.testSettings(kind,signal)}]));
const dayRows=computed(()=>m.value.calendar.rows),newCount=computed(()=>Object.values(m.value.calendar.mastery).filter(d=>d===m.value.calendar.day).length);
const growth=computed(()=>{const c=m.value.calendar,max=m.value.topics.length,y=n=>150-n/max*120;return `M35 ${y(c.baseline)}`+c.points.map((p,i)=>` H${35+(i+1)/(c.points.length+1)*600} V${y(p.total)}`).join('')+' H635';});
const demoText=computed(()=>{const x=m.value.demo;if(m.value.selected==='domain')return x===2?'1 ÷ 0：无意义，x=2被排除':`1 ÷ (${x}−2) = ${Number((1/(x-2)).toFixed(3))}，可以计算`;return x===-1?'分母为0：无意义，并不是结果为0':`分子 ${x-2}，分母 ${x+1}，结果 ${Number(((x-2)/(x+1)).toFixed(3))}${x===2?'：两个条件都满足':'：有意义，但不为0'}`;});
function switchTab(value){if(value==='learn')a.open('listen');else if(value==='recall')a.open('retell');else a.practice();}
function select({selectedValues}){a.choose(selectedValues[0]);picker.value=false;}
function duration(ms){const s=Math.floor((ms||0)/1000);return s<60?s+'秒':s<3600?Math.floor(s/60)+'分'+s%60+'秒':Math.floor(s/3600)+'小时'+Math.floor(s%3600/60)+'分';}
function formatter(item){const d=item.date,key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return {...item,bottomInfo:m.value.calendar.days[key]||m.value.calendar.activity[key]?'已学习':''};}
function photo(q,file){uploadError.value='';a.submitPhoto(q.id,file.file);}
function doReset(){if(a.reset(confirmed.value)){reset.value=false;confirmed.value=false;}}
function openRewards(){const r=m.value.rewardLedger;if(r){rewardGame.value=r.config.gameMinutes;rewardCash.value=r.config.cashYuan;rewardEnabled.value=r.config.enabled;}a.open('rewards');}
</script>
<template>
 <nav class="course-return-nav"><Button tag="a" href="../app-design/units.html?subject=math&term=lower" data-growing-back>← 返回上一级</Button></nav>
 <main class="student-fraction-course">
  <header class="course-heading"><div><p class="eyebrow">苏科版 · 八年级下册 · 第10章</p><h1>分式课堂</h1></div><div class="progress-ring"><strong>{{m.topics.filter(t=>t.mastered).length}}/{{m.topics.length}}</strong></div></header>
  <nav class="course-tools-nav" aria-label="课堂工具"><Button @click="a.navigate('../app-design/math-wrong-questions.html?unit=math-8b-10')">本单元错题</Button><Button @click="a.navigate('../app-design/math-explore-lab.html?chapter=math-8b-10')">交互</Button></nav>
  <section class="fraction-mastery"><strong>{{m.score}} / 100</strong><span>章节掌握度</span><progress :value="m.score" max="100"/><p>费曼技巧 30% · 应用练习 70%</p></section>
  <p v-if="m.message" role="status">{{m.message}}</p><p v-if="m.storageError" role="alert">{{m.storageError}}</p>
  <div v-if="['listen','retell','exam','result'].includes(m.view)" class="course-layout">
   <div class="mobile-lesson-select"><label>切换本章知识点</label><Field :model-value="m.node.title" readonly is-link @click="picker=true"/></div>
   <nav class="lesson-list" aria-label="本章微课"><h2>按知识点学习</h2><Button v-for="(topic,i) in m.topics" :key="topic.id" :aria-current="topic.id===m.selected?'page':undefined" @click="a.choose(topic.id)"><small>知识点 {{String(i+1).padStart(2,'0')}}</small><strong>{{topic.title}}</strong><small>{{topic.mastered?'已掌握':'待学习'}}</small></Button></nav>
   <section class="lesson-panel"><p class="eyebrow">分式 · 知识点 {{m.topics.findIndex(t=>t.id===m.selected)+1}}</p><h2>{{m.node.title}}</h2><nav class="lesson-tabs" aria-label="学习步骤"><Button v-for="item in [{id:'learn',title:'图文讲解'},{id:'recall',title:'闭卷复述'},{id:'practice',title:'应用练习'}]" :key="item.id" :aria-current="tab===item.id?'page':undefined" @click="switchTab(item.id)">{{item.title}}</Button></nav>
   <section v-if="m.view==='listen'" class="course-panel">
    <p class="eyebrow">一分钟看图课 · 跟老师一起想</p><div class="meta"><span>教材第{{m.node.page}}页 · 四幕图解短讲</span><span>{{String(Math.floor(m.elapsed/60)).padStart(2,'0')}}:{{String(Math.floor(m.elapsed%60)).padStart(2,'0')}}</span></div>
    <div class="lesson-controls actions"><Button class="btn" type="primary" @click="a.play">{{m.playing?'从头再听':'▶ 老师，开始讲吧'}}</Button><Button class="btn ghost" :disabled="!m.playing" @click="a.pause">{{m.paused?'继续播放':'暂停'}}</Button></div>
    <Collapse v-model="expanded" class="voice-settings"><CollapseItem :title="'内置讲课音频 · 约'+Math.round(m.audioDuration||0)+'秒 · 声音设置'" name="voice"><RadioGroup :model-value="m.rate" direction="horizontal" @update:model-value="a.rate"><Radio :name="0.9">稍慢</Radio><Radio :name="1">正常</Radio><Radio :name="1.1">稍快</Radio></RadioGroup><Button @click="a.stop">停止播放</Button><p>合成语音 · 离线播放</p></CollapseItem></Collapse><p class="muted">边听边看，画面自动切换；讲完图文会收起。</p>
    <div class="classroom"><div class="scene-header"><span>跟着老师看图</span><span>{{m.scene+1}} / 4</span></div><div class="scene-tabs"><Button v-for="(title,i) in ['先观察','找关键','推一步','避误区']" :key="i" :class="{chosen:m.scene===i}" :aria-pressed="m.scene===i" @click="a.scene(i)">{{i+1}}　{{title}}</Button></div>
    <h2 id="sceneTitle">{{m.lesson.title}}</h2><section class="textbook-card" aria-label="教材原文"><div class="textbook-head"><b>{{m.textbook.kind}}</b><span>苏科版八下 · 第{{m.textbook.pages}}页</span></div><article v-for="(entry,i) in m.textbook.entries" :key="i" class="textbook-entry"><h3>{{entry.title}}</h3><blockquote>{{entry.quote}}</blockquote></article><p v-if="m.textbook.summary" class="book-derived">{{m.textbook.summary}}</p><p class="book-key">{{m.textbook.key}}</p></section>
    <div class="lesson-visual class-board" v-html="m.lesson.visual"/>
    <section v-if="m.selected==='domain'&&m.scene===1||m.selected==='zero'&&m.scene===2" class="mini-lab"><p>代一个数：x = {{m.demo}}</p><Slider :model-value="m.demo" :min="m.selected==='domain'?0:-2" :max="m.selected==='domain'?4:3" :step="1" aria-label="代入x的值" @update:model-value="a.demo"/><p role="status">{{demoText}}</p></section>
    <p class="scene-caption">{{m.lesson.caption}}</p><div class="scene-navigation"><Button :disabled="m.scene===0" @click="a.scene(m.scene-1)">上一幕</Button><Button :disabled="m.scene===3" @click="a.scene(m.scene+1)">下一幕</Button></div><section class="teacher-script"><span class="teacher-avatar" aria-hidden="true">师</span><div><b>老师这样讲</b><p>{{m.lesson.narration}}</p></div></section></div><div class="actions"><Button type="primary" @click="a.open('retell')">已理解，收起图文并复述</Button></div>
   </section>
   <section v-else-if="m.view==='retell'" class="course-panel"><h2>用自己的话讲清楚</h2><p>它是什么？什么时候能用？举个例子，再提醒一个容易弄错的地方。</p><Field :model-value="m.record.draft" type="textarea" label="我的理解" rows="8" autosize maxlength="4000" :disabled="m.busy" @update:model-value="a.draft"/><div class="actions"><Button type="primary" :loading="m.busy" :disabled="m.busy" @click="a.grade">AI检查理解 / 10分</Button><Button v-if="m.busy" @click="a.cancel">取消等待</Button><Button @click="a.open('doubts')">我有疑问</Button><Button @click="a.open('listen')">再听一遍</Button></div>
    <section v-if="m.answer" aria-label="本次评分"><h3>{{m.answer.score}} / 10 · {{m.answer.score>=8&&!m.answer.criticalErrors.length?'概念理解已掌握':'先补上漏洞'}}</h3><p>{{m.answer.comment}}</p><article v-for="criterion in m.node.criteria" :key="criterion.id"><h4>{{criterion.name}} {{m.answer.criteria.find(c=>c.id===criterion.id).score}} / {{criterion.max}}</h4><p>{{m.answer.criteria.find(c=>c.id===criterion.id).evidence||'复述中没有相应证据。'}}</p><p>{{m.answer.criteria.find(c=>c.id===criterion.id).feedback}}</p></article><h4>讲对的地方</h4><p v-for="(good,i) in m.answer.good" :key="i">{{good}}</p><h4>要补上的漏洞</h4><p v-for="(gap,i) in [...m.answer.criticalErrors,...m.answer.gaps]" :key="i">{{gap}}</p><p>老师追问：{{m.answer.followup}}</p></section>
    <Collapse v-model="expanded"><CollapseItem title="历史复述记录" name="attempts"><article v-for="(attempt,i) in [...m.record.attempts].reverse()" :key="i"><h3>{{attempt.score}} / 10 · {{new Date(attempt.at).toLocaleString('zh-CN')}}</h3><p class="preserve">{{attempt.answer}}</p><p>{{attempt.comment}}</p><p v-for="(gap,j) in [...(attempt.criticalErrors||[]),...(attempt.gaps||[])]" :key="j">{{gap}}</p></article></CollapseItem></Collapse><Button type="primary" @click="a.practice">教材应用练习</Button>
   </section>
   <section v-else-if="m.view==='exam'&&!m.run" class="course-panel"><h2>教材与诊断验证 · {{m.questions.length}} 题</h2><p v-if="m.practiceError" role="alert">{{m.practiceError}}</p><p v-if="uploadError" role="alert">{{uploadError}}</p><article v-for="(q,i) in m.questions" :key="q.id" class="practice-question"><h3>{{i+1}}. {{q.prompt}}</h3><ol v-if="q.options" type="A"><li v-for="(option,j) in q.options" :key="j">{{option}}</li></ol><p v-if="q.origin">{{q.origin.label}}</p><div class="actions"><Uploader accept="image/jpeg,image/png,image/webp" capture="environment" result-type="file" :disabled="q.pending" :max-size="20*1024*1024" :after-read="file=>photo(q,file)" @oversize="uploadError='照片不能超过20MB，请压缩后再试。'"><Button :disabled="q.pending" :loading="q.pending">拍照 / 上传原稿</Button></Uploader><Button v-if="q.photos.length&&!q.pending" @click="a.submitPhoto(q.id)">{{q.unsaved?'重试保存与批改':'重新批改'}}</Button><Button v-if="q.pending" @click="a.cancelPhoto(q.id)">取消批改</Button></div><p role="status">{{q.message}}</p><div class="photos"><Button v-for="(image,j) in q.photos" :key="j" aria-label="查看原稿" @click="showImagePreview({images:q.photos,startPosition:j})"><img :src="image" alt="手写原稿"/></Button></div><StudentUploadHistory :uploads="q.uploads"/><article v-for="(g,j) in q.history" :key="j"><h4>{{g.historical?'历史批改':'本次批改'}} · {{g.needsReview?'待复核':g.score+' / 100'}}</h4><p>{{g.feedback}}</p><p v-for="(correction,k) in g.corrections||[]" :key="k">{{correction.location}}：{{correction.issue}} {{correction.correction}}</p></article></article><Button @click="a.special">真题与补充训练</Button></section>
   <section v-else-if="m.view==='exam'&&m.run" class="course-panel"><p>专项验证 {{m.run.i+1}} / {{m.run.items.length}}</p><h2>{{currentQuestion.stem}}</h2><Field v-if="currentQuestion.type==='fill'" :model-value="m.run.input" label="填写答案" maxlength="200" :disabled="m.run.answered" @update:model-value="a.examInput"/><RadioGroup v-else :model-value="m.run.picked" :disabled="m.run.answered" @update:model-value="a.pick"><CellGroup><Cell v-for="(option,i) in currentQuestion.options" :key="i" :title="option" clickable @click="!m.run.answered&&a.pick(i)"><template #right-icon><Radio :name="i"/></template></Cell></CellGroup></RadioGroup><section v-if="m.run.answered"><h3>{{m.run.answers.at(-1).ok?'答对了':'本题需巩固'}}</h3><p>正确答案：{{currentQuestion.type==='fill'?currentQuestion.answer[0]:currentQuestion.options[currentQuestion.answer]}}</p><p>{{currentQuestion.explanation}}</p></section><Button type="primary" @click="a.answerExam">{{m.run.answered?(m.run.i===m.run.items.length-1?'查看结果':'下一题'):'确认答案'}}</Button><p>{{currentQuestion.origin?.label}}</p></section>
   <section v-else-if="m.view==='result'&&m.run" class="course-panel"><h2>专项验证 {{m.run.answers.filter(row=>row.ok).length}} / {{m.run.items.length}}</h2><article v-for="row in m.run.answers.filter(row=>!row.ok)" :key="row.qid"><h3>{{m.run.items.find(q=>q.id===row.qid).stem}}</h3><p>本次作答：{{row.value}}</p><p>{{m.run.items.find(q=>q.id===row.qid).explanation}}</p></article><div class="actions"><Button @click="a.special">再练本知识点</Button><Button @click="a.next">下一个知识点</Button></div></section>
   </section>
  </div>
  <section v-else-if="m.view==='doubts'" class="course-panel"><div class="heading"><h2>我有疑问 · {{m.node.title}}</h2><Button icon="cross" aria-label="关闭答疑" @click="a.open('listen')"/></div><p>当前知识点仅作背景，也可询问其他问题。</p><article v-for="(turn,i) in m.record.doubts" :key="i"><h3>我的疑问</h3><p>{{turn.question}}</p><h3>老师的解释</h3><p>{{turn.response.answer}}</p><ol><li v-for="(step,j) in turn.response.steps" :key="j">{{step}}</li></ol><p>{{turn.response.example}}</p><p>{{turn.response.checkQuestion}}</p></article><Field :model-value="m.record.doubtDraft" type="textarea" label="我的疑问" rows="5" maxlength="2000" :disabled="m.busy" @update:model-value="a.doubtDraft"/><div class="actions"><Button type="primary" :loading="m.busy" :disabled="m.busy" @click="a.ask">提交疑问</Button><Button v-if="m.busy" @click="a.cancel">取消等待</Button></div></section>
  <section v-else-if="m.view==='progress'" class="course-panel"><div class="heading"><h2>学习日历与成长</h2><Button icon="cross" aria-label="关闭学习日历" @click="a.open('listen')"/></div><Calendar :poppable="false" :show-confirm="false" :min-date="new Date(2020,0,1)" :max-date="new Date(2040,11,31)" switch-mode="month" :style="{height:'420px'}" :formatter="formatter" @select="a.calendarDay"/><Button @click="a.calendarDay(new Date())">查看今天记录</Button><h3>{{m.calendar.day}} · 学习摘要</h3><p>新增掌握 {{newCount}} 个 · 当天有效学习 {{duration(m.calendar.activity[m.calendar.day])}}</p><Cell v-for="row in dayRows" :key="row.id" :title="row.title" :label="'复述 '+row.attempts+' 次 · 最高 '+row.best+'/10 · 练习 '+row.exams+' 轮 · 答对 '+row.correct+'/'+row.total+' 题'" is-link @click="a.choose(row.id)"/><h3>成长曲线 · 累计掌握 {{Object.keys(m.calendar.mastery).length}} / {{m.topics.length}}</h3><svg viewBox="0 0 680 180" class="growth" role="img" aria-label="累计首次掌握知识点曲线"><path :d="growth" fill="none" stroke="#22634b" stroke-width="3"/><text x="35" y="175">{{m.calendar.points[0]?.date||'暂无带日期记录'}}</text></svg><p v-if="m.calendar.baseline">{{m.calendar.baseline}} 个历史掌握记录缺少日期，作为累计起点保留。</p><p v-for="point in m.calendar.points" :key="point.date">{{point.date}} · 累计掌握 {{point.total}} 个</p><h3>各知识点学习效率</h3><Cell v-for="row in m.topics" :key="row.id" :title="row.title" :label="row.time" is-link @click="a.choose(row.id)"/><Collapse v-model="expanded"><CollapseItem title="每日有效学习时间" name="time"><p v-for="(ms,date) in m.calendar.activity" :key="date">{{date}} · {{duration(ms)}}</p></CollapseItem></Collapse></section>
  <section v-else-if="m.view==='sources'" class="course-panel"><div class="heading"><h2>教材、真题与补充训练</h2><Button icon="cross" aria-label="关闭题目来源" @click="a.open('listen')"/></div><p>教材与诊断题 {{m.sources.questions.length}} 道 · 转载真题 {{m.sources.real.length}} 道 · 原创补充 {{m.sources.supplemental.length}} 道</p><p>{{m.sources.status}}</p><Cell v-for="row in m.topics" :key="row.id" :title="row.title" :label="row.mastered?'概念已达标，可进入专项训练':'先学概念，AI达8分后解锁专项'" is-link @click="a.choose(row.id);row.mastered?a.special():a.open('listen')"/><Collapse v-model="expanded"><CollapseItem v-for="(items,name) in {转载真题:m.sources.real,原创补充:m.sources.supplemental,教材与诊断:m.sources.questions}" :key="name" :title="name" :name="name"><article v-for="q in items" :key="q.id"><h3>{{q.stem}}</h3><p>{{q.origin?.paper||q.origin?.label}}</p><p v-if="q.origin?.kind==='real'">原卷题号待核对</p><a v-if="q.origin?.url" :href="q.origin.url" target="_blank" rel="noopener noreferrer">查看公开转载来源</a></article></CollapseItem></Collapse></section>
  <section v-else-if="m.view==='settings'" class="course-panel"><StudentCourseSettings :services="services" @close="a.open('listen')"/><Button @click="confirmed=false;reset=true">重置本章学习进度</Button><p>清除本章进度、复述、答疑、日历和效率；保留原稿、AI配置与已获奖励。</p></section>
  <section v-else-if="m.view==='rewards'" class="course-panel"><div class="heading"><h2>本单元掌握与奖励</h2><Button icon="cross" aria-label="关闭掌握与奖励" @click="a.open('listen')"/></div><template v-if="m.rewardLedger"><p>已掌握 {{m.rewardLedger.done}} / {{m.rewardLedger.total}} 项。概念与教材应用均达标才计入。</p><p>已获得 {{m.rewardAmounts.game}} 分钟游戏 / {{(m.rewardAmounts.cash/100).toFixed(2)}} 元红包</p><p>已核销 {{m.rewardLedger.paidGame}} 分钟 / {{(m.rewardLedger.paidCash/100).toFixed(2)}} 元；可核销 {{m.rewardAmounts.availableGame}} 分钟 / {{(m.rewardAmounts.availableCash/100).toFixed(2)}} 元</p><Field v-model="rewardGame" label="游戏总分钟" type="number" :disabled="m.rewardLocked"/><Field v-model="rewardCash" label="红包总元" type="number" :disabled="m.rewardLocked"/><Checkbox v-model="rewardEnabled" :disabled="m.rewardLocked">启用奖励累计</Checkbox><Button :disabled="m.rewardLocked" @click="a.saveReward(rewardGame,rewardCash,rewardEnabled)">保存本单元奖励</Button><Field v-model="rewardParent" label="家长称呼" maxlength="30"/><Checkbox v-model="rewardConfirm">我是家长，确认已实际兑现本次额度</Checkbox><div class="actions"><Button :disabled="!rewardConfirm||!m.rewardAmounts.availableGame" @click="a.redeemReward('game',rewardParent,rewardConfirm)">核销游戏时间</Button><Button :disabled="!rewardConfirm||!m.rewardAmounts.availableCash" @click="a.redeemReward('cash',rewardParent,rewardConfirm)">核销红包</Button></div><p>本页只记账，不转账或控制游戏；家长确认不提供身份验证。重学不会重复获得同一份额度。</p><p v-for="(row,i) in m.rewardLedger.history" :key="i">{{row.legacy?'已承接旧版奖励与核销状态':new Date(row.at).toLocaleString('zh-CN')+' · '+row.parent+' · '+(row.kind==='game'?row.amount+' 分钟':(row.amount/100).toFixed(2)+' 元')}}</p></template><p v-else role="alert">{{m.rewardError}}</p></section>
  <footer><Button @click="a.choose(m.topics[Math.max(0,m.topics.findIndex(t=>t.id===m.selected)-1)].id)">上一个知识点</Button><Button @click="a.next">下一个知识点</Button></footer>
